use std::fmt;

#[derive(Debug)]
pub enum AppError {
    NotFound(String),
    Unauthorized,
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::NotFound(res) => write!(f, "Resource not found: {}", res),
            AppError::Unauthorized => write!(f, "Unauthorized access"),
        }
    }
}
